draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw a fruit
  ctx.fillStyle = 'red';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2*Math.PI);
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.stroke();

  // draw a stick figure eating the fruit
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2 - 50, 20, 0, 2*Math.PI); // head
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 - 30);
  ctx.lineTo(W/2 - 100, H/2 + 50); // body
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 - 10);
  ctx.lineTo(W/2 - 80, H/2 + 20); // arm
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 30);
  ctx.lineTo(W/2 - 80, H/2 + 60); // leg
  ctx.stroke();

  // make the stick figure move up and down
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 - 30 + 20*Math.sin(t));
  ctx.lineTo(W/2 - 100, H/2 + 50 + 20*Math.sin(t)); // body
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 - 10 + 20*Math.sin(t));
  ctx.lineTo(W/2 - 80, H/2 + 20 + 20*Math.sin(t)); // arm
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 30 + 20*Math.sin(t));
  ctx.lineTo(W/2 - 80, H/2 + 60 + 20*Math.sin(t)); // leg
  ctx.stroke();

  ctx.restore();
}
